cat > src/terminfo.rs <<'EOF'
//! Minimal terminfo database reader and parameterized string expander.

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, Write};
use std::path::PathBuf;

/// Indices of the capabilities we care about in the compiled terminfo format.
const NUM_COLORS: usize = 13;
const STR_SGR0: usize = 39;
const STR_SGR: usize = 131;
const STR_OP: usize = 297;
const STR_SETAF: usize = 359;
const STR_SETAB: usize = 360;

#[derive(Debug, Clone)]
pub struct TermInfo {
    pub numbers: HashMap<&'static str, u32>,
    pub strings: HashMap<&'static str, Vec<u8>>,
}

fn get_dbpath_for_term(term: &str) -> Option<PathBuf> {
    let first_char = term.chars().next()?;
    let mut dirs_to_search: Vec<PathBuf> = Vec::new();
    if let Some(dir) = env::var_os("TERMINFO") {
        dirs_to_search.push(PathBuf::from(dir));
    }
    if let Ok(dirs) = env::var("TERMINFO_DIRS") {
        for i in dirs.split(':') {
            if i.is_empty() {
                dirs_to_search.push(PathBuf::from("/usr/share/terminfo"));
            } else {
                dirs_to_search.push(PathBuf::from(i));
            }
        }
    } else {
        if let Some(mut homedir) = dirs::home_dir() {
            homedir.push(".terminfo");
            dirs_to_search.push(homedir);
        }
        dirs_to_search.push(PathBuf::from("/etc/terminfo"));
        dirs_to_search.push(PathBuf::from("/lib/terminfo"));
        dirs_to_search.push(PathBuf::from("/usr/share/terminfo"));
        dirs_to_search.push(PathBuf::from("/boot/system/data/terminfo"));
    }
    for mut p in dirs_to_search {
        if fs::metadata(&p).is_ok() {
            p.push(first_char.to_string());
            p.push(term);
            if fs::metadata(&p).is_ok() {
                return Some(p);
            }
            p.pop();
            p.pop();
            p.push(format!("{:x}", first_char as usize));
            p.push(term);
            if fs::metadata(&p).is_ok() {
                return Some(p);
            }
        }
    }
    None
}

fn read_i16(d: &[u8], off: usize) -> Option<i16> {
    if off + 2 > d.len() {
        return None;
    }
    Some(i16::from_le_bytes([d[off], d[off + 1]]))
}

fn read_i32(d: &[u8], off: usize) -> Option<i32> {
    if off + 4 > d.len() {
        return None;
    }
    Some(i32::from_le_bytes([d[off], d[off + 1], d[off + 2], d[off + 3]]))
}

impl TermInfo {
    pub fn from_env() -> Option<TermInfo> {
        let term = env::var("TERM").ok()?;
        TermInfo::from_name(&term)
    }

    pub fn from_name(name: &str) -> Option<TermInfo> {
        let path = get_dbpath_for_term(name)?;
        let data = fs::read(path).ok()?;
        TermInfo::parse(&data)
    }

    fn parse(d: &[u8]) -> Option<TermInfo> {
        let magic = read_i16(d, 0)?;
        let numsize = match magic {
            0o0432 => 2usize,
            0o1036 => 4usize,
            _ => return None,
        };
        let names_bytes = read_i16(d, 2)? as i64;
        let bools_bytes = read_i16(d, 4)? as i64;
        let numbers_count = read_i16(d, 6)? as i64;
        let string_offsets_count = read_i16(d, 8)? as i64;
        let string_table_bytes = read_i16(d, 10)? as i64;
        if names_bytes <= 0 || bools_bytes < 0 || numbers_count < 0 || string_offsets_count < 0 || string_table_bytes < 0 {
            return None;
        }
        let mut off = 12usize;
        let names_bytes = names_bytes as usize;
        let bools_bytes = bools_bytes as usize;
        let numbers_count = numbers_count as usize;
        let string_offsets_count = string_offsets_count as usize;
        let string_table_bytes = string_table_bytes as usize;
        if off + names_bytes > d.len() {
            return None;
        }
        off += names_bytes;
        if off + bools_bytes > d.len() {
            return None;
        }
        off += bools_bytes;
        if (names_bytes + bools_bytes) % 2 == 1 {
            off += 1;
        }
        let mut numbers = HashMap::new();
        for i in 0..numbers_count {
            let v: i64 = if numsize == 2 {
                read_i16(d, off)? as i64
            } else {
                read_i32(d, off)? as i64
            };
            off += numsize;
            if v >= 0 && i == NUM_COLORS {
                numbers.insert("colors", v as u32);
            }
        }
        let mut offsets = Vec::with_capacity(string_offsets_count);
        for _ in 0..string_offsets_count {
            offsets.push(read_i16(d, off)?);
            off += 2;
        }
        if off + string_table_bytes > d.len() {
            return None;
        }
        let table = &d[off..off + string_table_bytes];
        let mut strings = HashMap::new();
        let wanted: [(usize, &'static str); 5] = [
            (STR_SGR0, "sgr0"),
            (STR_SGR, "sgr"),
            (STR_OP, "op"),
            (STR_SETAF, "setaf"),
            (STR_SETAB, "setab"),
        ];
        for (idx, name) in wanted.iter() {
            if *idx < offsets.len() {
                let o = offsets[*idx];
                if o >= 0 {
                    let o = o as usize;
                    if o < table.len() {
                        let end = table[o..].iter().position(|&b| b == 0).map(|p| o + p).unwrap_or(table.len());
                        strings.insert(*name, table[o..end].to_vec());
                    }
                }
            }
        }
        Some(TermInfo { numbers, strings })
    }
}

#[derive(Clone, Debug)]
enum Param {
    Number(i32),
    Words(String),
}

/// Expand a parameterized terminfo string.
pub fn expand(cap: &[u8], params: &[i32]) -> Result<Vec<u8>, String> {
    let mut params: Vec<Param> = params.iter().map(|&p| Param::Number(p)).collect();
    while params.len() < 9 {
        params.push(Param::Number(0));
    }
    let mut static_vars: Vec<Param> = vec![Param::Number(0); 26];
    let mut dyn_vars: Vec<Param> = vec![Param::Number(0); 26];
    let mut stack: Vec<Param> = Vec::new();
    let mut out: Vec<u8> = Vec::new();
    let mut i = 0usize;
    // nesting for conditionals
    let mut if_depth: usize = 0;

    fn pop_num(stack: &mut Vec<Param>) -> Result<i32, String> {
        match stack.pop() {
            Some(Param::Number(n)) => Ok(n),
            Some(Param::Words(_)) => Err("expected number on stack".to_string()),
            None => Err("stack is empty".to_string()),
        }
    }

    while i < cap.len() {
        let c = cap[i];
        if c != b'%' {
            out.push(c);
            i += 1;
            continue;
        }
        i += 1;
        if i >= cap.len() {
            return Err("unexpected end".to_string());
        }
        let c = cap[i];
        i += 1;
        match c {
            b'%' => out.push(b'%'),
            b'c' => {
                let n = pop_num(&mut stack)?;
                out.push(n as u8);
            }
            b's' => match stack.pop() {
                Some(Param::Words(s)) => out.extend_from_slice(s.as_bytes()),
                Some(Param::Number(n)) => out.extend_from_slice(n.to_string().as_bytes()),
                None => return Err("stack is empty".to_string()),
            },
            b'd' => {
                let n = pop_num(&mut stack)?;
                out.extend_from_slice(n.to_string().as_bytes());
            }
            b'p' => {
                if i >= cap.len() {
                    return Err("unexpected end".to_string());
                }
                let d = cap[i];
                i += 1;
                if !(b'1'..=b'9').contains(&d) {
                    return Err("bad param number".to_string());
                }
                stack.push(params[(d - b'1') as usize].clone());
            }
            b'P' => {
                if i >= cap.len() {
                    return Err("unexpected end".to_string());
                }
                let d = cap[i];
                i += 1;
                let v = stack.pop().ok_or_else(|| "stack is empty".to_string())?;
                if (b'A'..=b'Z').contains(&d) {
                    static_vars[(d - b'A') as usize] = v;
                } else if (b'a'..=b'z').contains(&d) {
                    dyn_vars[(d - b'a') as usize] = v;
                } else {
                    return Err("bad variable name".to_string());
                }
            }
            b'g' => {
                if i >= cap.len() {
                    return Err("unexpected end".to_string());
                }
                let d = cap[i];
                i += 1;
                if (b'A'..=b'Z').contains(&d) {
                    stack.push(static_vars[(d - b'A') as usize].clone());
                } else if (b'a'..=b'z').contains(&d) {
                    stack.push(dyn_vars[(d - b'a') as usize].clone());
                } else {
                    return Err("bad variable name".to_string());
                }
            }
            b'\'' => {
                if i + 1 >= cap.len() {
                    return Err("unexpected end".to_string());
                }
                let ch = cap[i];
                if cap[i + 1] != b'\'' {
                    return Err("bad char constant".to_string());
                }
                i += 2;
                stack.push(Param::Number(ch as i32));
            }
            b'{' => {
                let mut n: i32 = 0;
                let mut ok = false;
                while i < cap.len() && cap[i].is_ascii_digit() {
                    n = n.wrapping_mul(10).wrapping_add((cap[i] - b'0') as i32);
                    i += 1;
                    ok = true;
                }
                if !ok || i >= cap.len() || cap[i] != b'}' {
                    return Err("bad integer constant".to_string());
                }
                i += 1;
                stack.push(Param::Number(n));
            }
            b'l' => match stack.pop() {
                Some(Param::Words(s)) => stack.push(Param::Number(s.len() as i32)),
                Some(Param::Number(_)) => return Err("expected string on stack".to_string()),
                None => return Err("stack is empty".to_string()),
            },
            b'+' | b'-' | b'*' | b'/' | b'm' | b'&' | b'|' | b'^' | b'=' | b'>' | b'<' | b'A' | b'O' => {
                let y = pop_num(&mut stack)?;
                let x = pop_num(&mut stack)?;
                let r = match c {
                    b'+' => x.wrapping_add(y),
                    b'-' => x.wrapping_sub(y),
                    b'*' => x.wrapping_mul(y),
                    b'/' => {
                        if y == 0 {
                            return Err("division by zero".to_string());
                        }
                        x.wrapping_div(y)
                    }
                    b'm' => {
                        if y == 0 {
                            return Err("division by zero".to_string());
                        }
                        x.wrapping_rem(y)
                    }
                    b'&' => x & y,
                    b'|' => x | y,
                    b'^' => x ^ y,
                    b'=' => (x == y) as i32,
                    b'>' => (x > y) as i32,
                    b'<' => (x < y) as i32,
                    b'A' => ((x != 0) && (y != 0)) as i32,
                    b'O' => ((x != 0) || (y != 0)) as i32,
                    _ => unreachable!(),
                };
                stack.push(Param::Number(r));
            }
            b'!' | b'~' => {
                let x = pop_num(&mut stack)?;
                let r = if c == b'!' { (x == 0) as i32 } else { !x };
                stack.push(Param::Number(r));
            }
            b'i' => {
                for p in params.iter_mut().take(2) {
                    if let Param::Number(n) = p {
                        *n += 1;
                    }
                }
            }
            b'?' => {
                if_depth += 1;
            }
            b't' => {
                let x = pop_num(&mut stack)?;
                if x == 0 {
                    // skip to matching %e or %;
                    let mut level = 0usize;
                    loop {
                        if i >= cap.len() {
                            return Err("unterminated conditional".to_string());
                        }
                        if cap[i] == b'%' && i + 1 < cap.len() {
                            let n = cap[i + 1];
                            i += 2;
                            match n {
                                b'?' => level += 1,
                                b';' => {
                                    if level == 0 {
                                        if if_depth > 0 {
                                            if_depth -= 1;
                                        }
                                        break;
                                    }
                                    level -= 1;
                                }
                                b'e' => {
                                    if level == 0 {
                                        break;
                                    }
                                }
                                _ => {}
                            }
                        } else {
                            i += 1;
                        }
                    }
                }
            }
            b'e' => {
                // we reached an else after executing the then-branch: skip to matching %;
                let mut level = 0usize;
                loop {
                    if i >= cap.len() {
                        return Err("unterminated conditional".to_string());
                    }
                    if cap[i] == b'%' && i + 1 < cap.len() {
                        let n = cap[i + 1];
                        i += 2;
                        match n {
                            b'?' => level += 1,
                            b';' => {
                                if level == 0 {
                                    if if_depth > 0 {
                                        if_depth -= 1;
                                    }
                                    break;
                                }
                                level -= 1;
                            }
                            _ => {}
                        }
                    } else {
                        i += 1;
                    }
                }
            }
            b';' => {
                if if_depth > 0 {
                    if_depth -= 1;
                }
            }
            b'0'..=b'9' | b':' | b'.' | b'#' | b' ' => {
                // printf-style formatting: %[[:]flags][width[.precision]][doxXs]
                let mut j = i - 1;
                let mut flags_alt = false;
                let mut flags_left = false;
                let mut flags_space = false;
                let mut flags_plus = false;
                let mut flags_zero = false;
                if cap[j] == b':' {
                    j += 1;
                }
                while j < cap.len() {
                    match cap[j] {
                        b'#' => flags_alt = true,
                        b'-' => flags_left = true,
                        b' ' => flags_space = true,
                        b'+' => flags_plus = true,
                        b'0' => flags_zero = true,
                        _ => break,
                    }
                    j += 1;
                }
                let mut width: usize = 0;
                while j < cap.len() && cap[j].is_ascii_digit() {
                    width = width * 10 + (cap[j] - b'0') as usize;
                    j += 1;
                }
                let mut precision: Option<usize> = None;
                if j < cap.len() && cap[j] == b'.' {
                    j += 1;
                    let mut p = 0usize;
                    while j < cap.len() && cap[j].is_ascii_digit() {
                        p = p * 10 + (cap[j] - b'0') as usize;
                        j += 1;
                    }
                    precision = Some(p);
                }
                if j >= cap.len() {
                    return Err("unexpected end".to_string());
                }
                let conv = cap[j];
                i = j + 1;
                let s: String = match conv {
                    b'd' | b'o' | b'x' | b'X' => {
                        let n = pop_num(&mut stack)?;
                        let mut body = match conv {
                            b'd' => (n.unsigned_abs()).to_string(),
                            b'o' => format!("{:o}", n),
                            b'x' => format!("{:x}", n),
                            _ => format!("{:X}", n),
                        };
                        if let Some(p) = precision {
                            while body.len() < p {
                                body.insert(0, '0');
                            }
                        }
                        if flags_alt {
                            match conv {
                                b'o' => body.insert(0, '0'),
                                b'x' => body.insert_str(0, "0x"),
                                b'X' => body.insert_str(0, "0X"),
                                _ => {}
                            }
                        }
                        if conv == b'd' {
                            if n < 0 {
                                body.insert(0, '-');
                            } else if flags_plus {
                                body.insert(0, '+');
                            } else if flags_space {
                                body.insert(0, ' ');
                            }
                        }
                        body
                    }
                    b's' => match stack.pop() {
                        Some(Param::Words(s)) => {
                            let mut s = s;
                            if let Some(p) = precision {
                                s.truncate(p);
                            }
                            s
                        }
                        Some(Param::Number(n)) => n.to_string(),
                        None => return Err("stack is empty".to_string()),
                    },
                    _ => return Err("bad format".to_string()),
                };
                let mut s = s;
                if s.len() < width {
                    let pad = width - s.len();
                    if flags_left {
                        s.push_str(&" ".repeat(pad));
                    } else if flags_zero && conv != b's' {
                        s.insert_str(0, &"0".repeat(pad));
                    } else {
                        s.insert_str(0, &" ".repeat(pad));
                    }
                }
                out.extend_from_slice(s.as_bytes());
            }
            _ => return Err(format!("unrecognized format option {}", c as char)),
        }
    }
    Ok(out)
}

/// A terminal that writes escape sequences derived from terminfo.
pub struct Terminal<W: Write> {
    out: W,
    ti: TermInfo,
    num_colors: u32,
}

impl<W: Write> Terminal<W> {
    pub fn new(out: W, ti: TermInfo) -> Terminal<W> {
        let nc = if ti.strings.contains_key("setaf") && ti.strings.contains_key("setab") {
            ti.numbers.get("colors").copied().unwrap_or(0)
        } else {
            0
        };
        Terminal { out, ti, num_colors: nc }
    }

    fn dim_if_necessary(&self, color: u32) -> u32 {
        if color >= self.num_colors && color >= 8 && color < 16 {
            color - 8
        } else {
            color
        }
    }

    fn apply_cap(&mut self, cmd: &str, params: &[i32]) -> io::Result<()> {
        let cap = match self.ti.strings.get(cmd) {
            Some(c) => c.clone(),
            None => return Err(io::Error::new(io::ErrorKind::Other, "not supported")),
        };
        let s = expand(&cap, params).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
        self.out.write_all(&s)
    }

    pub fn fg(&mut self, color: u32) -> io::Result<()> {
        let color = self.dim_if_necessary(color);
        if self.num_colors > color {
            return self.apply_cap("setaf", &[color as i32]);
        }
        Err(io::Error::new(io::ErrorKind::Other, "color out of range"))
    }

    pub fn reset(&mut self) -> io::Result<()> {
        let cmd: Vec<u8> = if let Some(c) = self.ti.strings.get("sgr0") {
            expand(c, &[]).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?
        } else if let Some(c) = self.ti.strings.get("sgr") {
            expand(c, &[0, 0, 0, 0, 0, 0, 0, 0, 0]).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?
        } else if let Some(c) = self.ti.strings.get("op") {
            expand(c, &[]).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?
        } else {
            return Err(io::Error::new(io::ErrorKind::Other, "not supported"));
        };
        self.out.write_all(&cmd)
    }

    pub fn write_all(&mut self, buf: &[u8]) -> io::Result<()> {
        self.out.write_all(buf)
    }

    pub fn flush(&mut self) -> io::Result<()> {
        self.out.flush()
    }
}
