                        let n = pop_num(&mut stack)?;
                        let mut body = match conv {
                            b'd' => (n.unsigned_abs()).to_string(),
                            b'o' => format!("{:o}", n),
                            b'x' => format!("{:x}", n),
                            _ => format!("{:X}", n),
                        };
                        if let Some(p) = precision {
                            while body.len() < p {
                                body.insert(0, '0');
                            }
                        }
                        if flags_alt {
                            match conv {
                                b'o' => body.insert(0, '0'),
                                b'x' => body.insert_str(0, "0x"),
                                b'X' => body.insert_str(0, "0X"),
                                _ => {}
                            }
                        }
                        if conv == b'd' {
                            if n < 0 {
                                body.insert(0, '-');
                            } else if flags_plus {
                                body.insert(0, '+');
                            } else if flags_space {
                                body.insert(0, ' ');
                            }
                        }
                        body
                    }
                    b's' => match stack.pop() {
                        Some(Param::Words(s)) => {
                            let mut s = s;
                            if let Some(p) = precision {
                                s.truncate(p);
                            }
                            s
                        }
                        Some(Param::Number(n)) => n.to_string(),
                        None => return Err("stack is empty".to_string()),
                    },
                    _ => return Err("bad format".to_string()),
                };
                let mut s = s;
                if s.len() < width {
                    let pad = width - s.len();
                    if flags_left {
                        s.push_str(&" ".repeat(pad));
                    } else if flags_zero && conv != b's' {
                        s.insert_str(0, &"0".repeat(pad));
                    } else {
                        s.insert_str(0, &" ".repeat(pad));
                    }
                }
                out.extend_from_slice(s.as_bytes());
            }
            _ => return Err(format!("unrecognized format option {}", c as char)),
        }
    }
    Ok(out)
}

/// A terminal that writes escape sequences derived from terminfo.
pub struct Terminal<W: Write> {
    out: W,
    ti: TermInfo,
    num_colors: u32,
}

impl<W: Write> Terminal<W> {
    pub fn new(out: W, ti: TermInfo) -> Terminal<W> {
        let nc = if ti.strings.contains_key("setaf") && ti.strings.contains_key("setab") {
            ti.numbers.get("colors").copied().unwrap_or(0)
        } else {
            0
        };
        Terminal { out, ti, num_colors: nc }
    }

    fn dim_if_necessary(&self, color: u32) -> u32 {
        if color >= self.num_colors && color >= 8 && color < 16 {
            color - 8
        } else {
            color
        }
    }

    fn apply_cap(&mut self, cmd: &str, params: &[i32]) -> io::Result<()> {
        let cap = match self.ti.strings.get(cmd) {
            Some(c) => c.clone(),
            None => return Err(io::Error::new(io::ErrorKind::Other, "not supported")),
        };
        let s = expand(&cap, params).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
        self.out.write_all(&s)
    }

    pub fn fg(&mut self, color: u32) -> io::Result<()> {
        let color = self.dim_if_necessary(color);
        if self.num_colors > color {
            return self.apply_cap("setaf", &[color as i32]);
        }
        Err(io::Error::new(io::ErrorKind::Other, "color out of range"))
    }

    pub fn reset(&mut self) -> io::Result<()> {
        let cmd: Vec<u8> = if let Some(c) = self.ti.strings.get("sgr0") {
            expand(c, &[]).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?
        } else if let Some(c) = self.ti.strings.get("sgr") {
            expand(c, &[0, 0, 0, 0, 0, 0, 0, 0, 0]).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?
        } else if let Some(c) = self.ti.strings.get("op") {
            expand(c, &[]).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?
        } else {
            return Err(io::Error::new(io::ErrorKind::Other, "not supported"));
        };
        self.out.write_all(&cmd)
    }

    pub fn write_all(&mut self, buf: &[u8]) -> io::Result<()> {
        self.out.write_all(buf)
    }

    pub fn flush(&mut self) -> io::Result<()> {
        self.out.flush()
    }
}
