            Kind::Filename => BRIGHT_GREEN,
            Kind::Text => WHITE,
            Kind::MatchText => BRIGHT_YELLOW,
            Kind::Other => BRIGHT_CYAN,
            Kind::Info => BRIGHT_CYAN,
            Kind::Error => BRIGHT_RED,
        }
    }

    fn is_stderr(self) -> bool {
        matches!(self, Kind::Info | Kind::Error)
    }
}

pub struct Console {
