        let err = TermInfo::from_env().map(|ti| Terminal::new(io::stderr(), ti));
        Console {
            out,
            err,
            color,
            out_color: None,
            err_color: None,
        }
    }

    fn fail() -> ! {
        process::exit(1);
    }

