                    }
                    self.out_color = Some(c);
                }
            }
            if term.write_all(text).is_err() {
                Console::fail();
            }
            let _ = term.flush();
        }
    }

    pub fn write_str(&mut self, kind: Kind, text: &str) {
        self.write(kind, text.as_bytes());
    }

    pub fn reset(&mut self) {
