cat > src/cli.rs <<'EOF'
//! Command line parsing emulating the behaviour of clap 2.x as used by ambr.

use std::collections::HashMap;
use std::ffi::OsString;
use std::io::Write;
use std::os::unix::ffi::OsStringExt;
use std::path::Path;
use std::process;

use crate::strsim::jaro_winkler;

pub const VERSION: &str = "0.6.0";
pub const NAME: &str = "ambr";

struct FlagDef {
    name: &'static str,
    short: Option<char>,
    help: &'static str,
}

struct OptDef {
    name: &'static str,
    value_name: &'static str,
    default: &'static str,
    help: &'static str,
}

const FLAGS: &[FlagDef] = &[
    FlagDef { name: "key-from-file", short: None, help: "Use file contents of KEYWORD as keyword for search" },
    FlagDef { name: "rep-from-file", short: None, help: "Use file contents of REPLACEMENT as keyword for replacement" },
    FlagDef { name: "verbose", short: None, help: "Verbose message" },
    FlagDef { name: "regex", short: Some('r'), help: "Enable regular expression search" },
    FlagDef { name: "column", short: None, help: "Enable column output" },
    FlagDef { name: "row", short: None, help: "Enable row output" },
    FlagDef { name: "binary", short: None, help: "Enable binary file search" },
    FlagDef { name: "statistics", short: None, help: "Enable statistics output" },
    FlagDef { name: "skipped", short: None, help: "Enable skipped file output" },
    FlagDef { name: "preserve-time", short: None, help: "Enable timestamp preserve" },
    FlagDef { name: "no-interactive", short: None, help: "Disable interactive replace" },
    FlagDef { name: "no-recursive", short: None, help: "Disable recursive directory search" },
    FlagDef { name: "no-symlink", short: None, help: "Disable symbolic link follow" },
    FlagDef { name: "no-color", short: None, help: "Disable colored output" },
    FlagDef { name: "no-file", short: None, help: "Disable filename output" },
    FlagDef { name: "no-skip-vcs", short: None, help: "Disable vcs directory ( .hg/.git/.svn ) skip" },
    FlagDef { name: "no-skip-gitignore", short: None, help: "Disable .gitignore skip" },
    FlagDef { name: "no-fixed-order", short: None, help: "Disable output order guarantee" },
    FlagDef { name: "no-parent-ignore", short: None, help: "Disable .*ignore file search at parent directories" },
    FlagDef { name: "tbm", short: None, help: "[Experimental] Enable TBM matcher" },
    FlagDef { name: "sse", short: None, help: "[Experimental] Enable SSE 4.2" },
    FlagDef { name: "help", short: Some('h'), help: "Prints help information" },
    FlagDef { name: "version", short: Some('V'), help: "Prints version information" },
];

const OPTS: &[OptDef] = &[
    OptDef { name: "max-threads", value_name: "NUM", default: "10", help: "Number of max threads" },
    OptDef { name: "size-per-thread", value_name: "BYTES", default: "1048576", help: "File size per one thread" },
    OptDef { name: "bin-check-bytes", value_name: "BYTES", default: "256", help: "Read size for checking binary" },
    OptDef { name: "mmap-bytes", value_name: "BYTES", default: "1048576", help: "[Experimental] Minimum size for using mmap" },
];

const POSITIONALS: &[(&str, &str)] = &[
    ("<KEYWORD>", "Keyword for search"),
    ("<REPLACEMENT>", "Keyword for replace"),
    ("<PATHS>...", "Search paths"),
];

#[derive(Debug, Clone, Default)]
pub struct Args {
    pub flags: HashMap<&'static str, usize>,
    pub max_threads: usize,
    pub size_per_thread: usize,
    pub bin_check_bytes: usize,
    pub mmap_bytes: usize,
    pub keyword: Vec<u8>,
    pub replacement: Vec<u8>,
    pub paths: Vec<OsString>,
}

impl Args {
    pub fn flag(&self, name: &str) -> bool {
        self.flags.get(name).copied().unwrap_or(0) > 0
    }
}

fn is_tty(fd: i32) -> bool {
    unsafe { libc::isatty(fd) == 1 }
}

fn find_flag(name: &str) -> Option<&'static FlagDef> {
    FLAGS.iter().find(|f| f.name == name)
}

fn find_opt(name: &str) -> Option<&'static OptDef> {
    OPTS.iter().find(|o| o.name == name)
}

fn opt_display(o: &OptDef) -> String {
    format!("--{} <{}>", o.name, o.value_name)
}

struct Colors {
    on: bool,
}

impl Colors {
    fn error(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[1;31m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn warning(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[33m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn good(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[32m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
}

fn help_usage(bin: &str) -> String {
    format!("{} [FLAGS] [OPTIONS] <KEYWORD> <REPLACEMENT> [PATHS]...", bin)
}

/// Build the "smart" usage from the list of used argument names (non positional).
fn smart_usage(bin: &str, used: &[&str]) -> String {
    let mut names: Vec<&str> = used.to_vec();
    names.sort();
    names.dedup();
    let mut usage = String::new();
    usage.push_str(bin);
    usage.push_str(" <KEYWORD> <REPLACEMENT>");
    for n in names {
        if let Some(f) = find_flag(n) {
            usage.push_str(&format!(" --{}", f.name));
        } else if let Some(o) = find_opt(n) {
            usage.push(' ');
            usage.push_str(&opt_display(o));
        }
    }
    usage
}

fn usage_from(bin: &str, used: &[&str]) -> String {
    if used.is_empty() {
        help_usage(bin)
    } else {
        smart_usage(bin, used)
    }
}

fn print_error_and_exit(message: String, usage: Option<String>, colors: &Colors) -> ! {
    let mut s = String::new();
    s.push_str(&format!("{} {}\n", colors.error("error:"), message));
    if let Some(u) = usage {
        s.push_str(&format!("\nUSAGE:\n    {}\n\nFor more information try {}\n", u, colors.good("--help")));
    }
    let stderr = std::io::stderr();
    let mut h = stderr.lock();
    let _ = h.write_all(s.as_bytes());
    let _ = h.flush();
    process::exit(1);
}

fn did_you_mean(arg: &str) -> Option<&'static str> {
    let mut candidate: Option<(f64, &'static str)> = None;
    let longs = FLAGS.iter().map(|f| f.name).chain(OPTS.iter().map(|o| o.name));
    for pv in longs {
        let confidence = jaro_winkler(arg, pv);
        if confidence > 0.8 && (candidate.is_none() || candidate.as_ref().unwrap().0 < confidence) {
            candidate = Some((confidence, pv));
        }
    }
    candidate.map(|c| c.1)
}

pub fn help_text(bin: &str, color: bool) -> String {
    let c = Colors { on: color };
    let mut s = String::new();
    s.push_str(&format!("{} {}\n", c.good(NAME), VERSION));
    if color {
        s.push_str(&format!("\x1b[33m\nUSAGE:\x1b[0m\n"));
    } else {
        s.push_str("\nUSAGE:\n");
    }
    s.push_str(&format!("    {}\n\n", help_usage(bin)));
    // FLAGS
    if color {
        s.push_str("\x1b[33mFLAGS:\n\x1b[0m");
    } else {
        s.push_str("FLAGS:\n");
    }
    let longest_flag = FLAGS.iter().map(|f| f.name.len() + 2).max().unwrap_or(0);
    for f in FLAGS {
        let long = format!("--{}", f.name);
        let pad = longest_flag + 4 - long.len();
        match f.short {
            Some(sc) => {
                let short = format!("-{}", sc);
                s.push_str(&format!("    {}, {}{}{}\n", c.good(&short), c.good(&long), " ".repeat(pad), f.help));
            }
            None => {
                s.push_str(&format!("        {}{}{}\n", c.good(&long), " ".repeat(pad), f.help));
            }
        }
    }
    s.push('\n');
    if color {
        s.push_str("\x1b[33mOPTIONS:\n\x1b[0m");
    } else {
        s.push_str("OPTIONS:\n");
    }
    let longest_opt = OPTS.iter().map(|o| opt_display(o).len()).max().unwrap_or(0);
    for o in OPTS {
        let plain = opt_display(o);
        let pad = longest_opt + 4 - plain.len();
        let long = format!("--{}", o.name);
        let val = format!("<{}>", o.value_name);
        s.push_str(&format!(
            "        {} {}{}{} [default: {}]\n",
            c.good(&long),
            c.good(&val),
            " ".repeat(pad),
            o.help,
            c.good(o.default)
        ));
    }
    s.push('\n');
    if color {
        s.push_str("\x1b[33mARGS:\n\x1b[0m");
    } else {
        s.push_str("ARGS:\n");
    }
    let longest_pos = POSITIONALS.iter().map(|p| p.0.len()).max().unwrap_or(0);
    for p in POSITIONALS {
        let pad = longest_pos + 4 - p.0.len();
        s.push_str(&format!("    {}{}{}\n", c.good(p.0), " ".repeat(pad), p.1));
    }
    s
}

fn print_help_and_exit(bin: &str) -> ! {
    let text = help_text(bin, is_tty(1));
    let stdout = std::io::stdout();
    let mut h = stdout.lock();
    let _ = h.write_all(text.as_bytes());
    let _ = h.flush();
    process::exit(0);
}

fn print_version_and_exit() -> ! {
    let stdout = std::io::stdout();
    let mut h = stdout.lock();
    let _ = h.write_all(format!("{} {}\n", NAME, VERSION).as_bytes());
    let _ = h.flush();
    process::exit(0);
}

fn os_to_string(s: &OsString) -> String {
    s.to_string_lossy().into_owned()
}

pub fn parse(argv: Vec<OsString>) -> Args {
    let bin = argv
        .first()
        .map(|a| {
            Path::new(a)
                .file_name()
                .map(|f| f.to_string_lossy().into_owned())
                .unwrap_or_else(|| a.to_string_lossy().into_owned())
        })
        .unwrap_or_else(|| NAME.to_string());
    let colors = Colors { on: is_tty(2) };

    // Matcher state: names in order of first appearance, with occurrence counts
    let mut used: Vec<&'static str> = Vec::new();
    let mut counts: HashMap<&'static str, usize> = HashMap::new();
    let mut values: HashMap<&'static str, OsString> = HashMap::new();
    let mut positionals: Vec<OsString> = Vec::new();
    let mut pending: Option<&'static str> = None;
    let mut trailing = false;

    fn record(used: &mut Vec<&'static str>, counts: &mut HashMap<&'static str, usize>, name: &'static str) {
        if !used.contains(&name) {
            used.push(name);
        }
        *counts.entry(name).or_insert(0) += 1;
    }

    for arg in argv.iter().skip(1) {
        let bytes = arg.clone().into_vec();
