                let (name, val): (String, Option<OsString>) = match rest.find('=') {
                    Some(idx) => {
                        let v = bytes[2 + idx + 1..].to_vec();
                        (rest[..idx].to_string(), Some(OsString::from_vec(v)))
                    }
                    None => (rest.clone(), None),
                };
