//! Search/replace pipeline: finder -> matchers -> sorter -> replacer -> main.

use std::collections::HashMap;
use std::ffi::OsString;
use std::fs::{self, File};
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::sync::mpsc::{Receiver, Sender};
use std::sync::{Arc, Mutex};
use std::time::Instant;

use ignore::gitignore::{Gitignore, GitignoreBuilder};

use crate::console::{Console, Kind};

pub enum Msg<T> {
    Dat(usize, T),
    Info(String),
    Err(String),
    Time(usize, f64, f64),
    End,
}

#[derive(Debug, Clone)]
pub struct Match {
    pub start: usize,
    pub end: usize,
    pub replacement: Vec<u8>,
}

#[derive(Debug, Clone)]
pub struct PathMatch {
    pub path: PathBuf,
    pub matches: Vec<Match>,
}

#[allow(deprecated)]
fn kind_str(e: &io::Error) -> String {
    use std::error::Error;
    e.description().to_string()
}

fn secs(start: Instant) -> f64 {
    start.elapsed().as_secs_f64()
}

// ---------------------------------------------------------------------------
// Finder
// ---------------------------------------------------------------------------

pub struct Finder {
    pub paths: Vec<OsString>,
    pub recursive: bool,
    pub symlink: bool,
    pub skip_vcs: bool,
    pub skip_gitignore: bool,
    pub parent_ignore: bool,
    pub print_skipped: bool,
    pub id: usize,
}

struct FinderState {
    infos: Vec<String>,
    errors: Vec<String>,
    ignore: Option<Gitignore>,
    seq: usize,
}

fn build_gitignore(root: &Path, file: &Path) -> Option<Gitignore> {
    let mut builder = GitignoreBuilder::new(root);
    let _ = builder.add(file);
    builder.build().ok()
}

fn is_vcs_name(name: &std::ffi::OsStr) -> bool {
    name == ".git" || name == ".hg" || name == ".svn" || name == ".bzr"
}

impl Finder {
    pub fn run(self, txs: Vec<Sender<Msg<PathBuf>>>) {
        let start = Instant::now();
        let mut st = FinderState {
            infos: Vec::new(),
            errors: Vec::new(),
            ignore: None,
            seq: 0,
        };
        let paths = self.paths.clone();
        for p in paths {
            let path = PathBuf::from(&p);
            if self.skip_gitignore && self.parent_ignore {
                self.parent_search(&path, &mut st);
            }
            let ignore = st.ignore.clone();
            self.find_top(&path, ignore, &mut st, &txs);
        }
        if !txs.is_empty() {
            for i in st.infos.drain(..) {
                let _ = txs[0].send(Msg::Info(i));
            }
            for e in st.errors.drain(..) {
                let _ = txs[0].send(Msg::Err(e));
            }
            let _ = txs[0].send(Msg::Time(self.id, 0.0, secs(start)));
        }
        for tx in &txs {
            let _ = tx.send(Msg::End);
        }
    }

    fn parent_search(&self, path: &Path, st: &mut FinderState) {
        let md = match fs::metadata(path) {
            Ok(m) => m,
            Err(e) => {
                st.errors.push(format!("{} @ {}", e, path.display()));
                return;
            }
        };
        let mut base: PathBuf = if md.is_dir() {
            path.join("..")
        } else {
            match path.parent() {
                Some(p) => p.to_path_buf(),
                None => return,
            }
        };
        loop {
            if fs::metadata(&base).is_err() {
                return;
            }
            let gi = base.join(".gitignore");
            if gi.is_file() {
                st.infos
                    .push(format!("Found .gitignore at the parent directory: {:?}\n", base));
                st.ignore = build_gitignore(&base, &gi);
                return;
            }
            match fs::canonicalize(&base) {
                Ok(c) => {
                    if c.parent().is_none() {
                        return;
                    }
                }
                Err(_) => return,
            }
            base = base.join("..");
        }
    }

    fn send(&self, path: PathBuf, st: &mut FinderState, txs: &[Sender<Msg<PathBuf>>]) {
        let idx = if txs.is_empty() { 0 } else { st.seq % txs.len() };
        let _ = txs[idx].send(Msg::Dat(st.seq, path));
        st.seq += 1;
    }

    fn find_top(&self, path: &Path, ignore: Option<Gitignore>, st: &mut FinderState, txs: &[Sender<Msg<PathBuf>>]) {
        let md = match fs::metadata(path) {
            Ok(m) => m,
            Err(e) => {
                st.errors.push(format!("{} @ {}", e, path.display()));
                return;
            }
        };
        if md.is_file() {
            if let Some(ig) = &ignore {
                if ig.matched(path, false).is_ignore() {
                    if self.print_skipped {
                        st.infos.push(format!("Skip (.gitignore): {:?}", path));
                    }
                    return;
                }
            }
            self.send(path.to_path_buf(), st, txs);
        } else {
            self.find_dir(path, ignore, st, txs);
        }
    }

    fn find_dir(&self, dir: &Path, ignore: Option<Gitignore>, st: &mut FinderState, txs: &[Sender<Msg<PathBuf>>]) {
        let rd = match fs::read_dir(dir) {
            Ok(r) => r,
            Err(e) => {
                st.errors.push(format!("{} @ {}", e, dir.display()));
                return;
            }
        };
        let mut ignore = ignore;
        if self.skip_gitignore {
            let gi = dir.join(".gitignore");
            if gi.is_file() {
                ignore = build_gitignore(dir, &gi);
            }
        }
        for entry in rd {
            let entry = match entry {
                Ok(e) => e,
                Err(_) => continue,
            };
            let name = entry.file_name();
            let child = dir.join(&name);
            if self.skip_vcs && is_vcs_name(&name) {
                if self.print_skipped {
                    st.infos.push(format!("Skip (vcs file)  : {:?}", child));
                }
                continue;
            }
            let ft = match entry.file_type() {
                Ok(t) => t,
                Err(_) => continue,
            };
            let md = if ft.is_symlink() {
                if !self.symlink {
                    continue;
                }
                match fs::metadata(&child) {
                    Ok(m) => m,
                    Err(_) => continue,
                }
            } else {
                match entry.metadata() {
                    Ok(m) => m,
                    Err(_) => continue,
                }
            };
            if let Some(ig) = &ignore {
                if ig.matched(&child, md.is_dir()).is_ignore() {
                    if self.print_skipped {
                        st.infos.push(format!("Skip (.gitignore): {:?}", child));
                    }
                    continue;
                }
            }
            if md.is_file() {
                self.send(child, st, txs);
            } else if md.is_dir() {
                if self.recursive {
                    self.find_dir(&child, ignore.clone(), st, txs);
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Matcher
// ---------------------------------------------------------------------------

pub enum Pattern {
    Fixed(Vec<u8>),
    Regex(Option<regex::Regex>),
}

pub struct Matcher {
    pub id: usize,
    pub pattern: Arc<Pattern>,
    pub replacement: Arc<Vec<u8>>,
    pub binary: bool,
    pub bin_check_bytes: usize,
    pub size_per_thread: usize,
    pub print_skipped: bool,
}

impl Matcher {
    pub fn run(self, rx: Receiver<Msg<PathBuf>>, tx: Sender<Msg<PathMatch>>) {
        let start = Instant::now();
        let mut infos: Vec<String> = Vec::new();
        let mut errors: Vec<String> = Vec::new();
        loop {
            match rx.recv() {
                Ok(Msg::Dat(seq, path)) => {
                    let matches = self.search(&path, &mut infos, &mut errors);
                    let _ = tx.send(Msg::Dat(seq, PathMatch { path, matches }));
                }
                Ok(Msg::Info(m)) => {
                    let _ = tx.send(Msg::Info(m));
                }
                Ok(Msg::Err(m)) => {
                    let _ = tx.send(Msg::Err(m));
                }
                Ok(Msg::Time(id, b, t)) => {
                    let _ = tx.send(Msg::Time(id, b, t));
                }
                Ok(Msg::End) => {
                    for i in infos.drain(..) {
                        let _ = tx.send(Msg::Info(i));
                    }
                    for e in errors.drain(..) {
                        let _ = tx.send(Msg::Err(e));
                    }
                    let _ = tx.send(Msg::Time(self.id, 0.0, secs(start)));
                    let _ = tx.send(Msg::End);
                    break;
                }
                Err(_) => break,
            }
        }
    }

    fn search(&self, path: &Path, infos: &mut Vec<String>, errors: &mut Vec<String>) -> Vec<Match> {
        let mut file = match File::open(path) {
            Ok(f) => f,
            Err(e) => {
                errors.push(format!("{} @ {:?}\n", kind_str(&e), path));
                return Vec::new();
            }
        };
        let mut content: Vec<u8> = Vec::new();
        if let Err(e) = file.read_to_end(&mut content) {
            errors.push(format!("{} @ {:?}\n", kind_str(&e), path));
            return Vec::new();
        }
        if !self.binary {
            let check = if content.len() < self.bin_check_bytes { content.len() } else { self.bin_check_bytes };
            if content[..check].contains(&0u8) {
                if self.print_skipped {
                    infos.push(format!("Skip (binary)    : {:?}", path));
                }
                return Vec::new();
            }
        }
        // Mimic the chunk computation of the original (division by size per thread).
        let _chunks = content.len() / self.size_per_thread;
        find_matches(&self.pattern, &self.replacement, &content)
    }
}

pub fn find_matches(pattern: &Pattern, replacement: &[u8], content: &[u8]) -> Vec<Match> {
    let mut result = Vec::new();
    match pattern {
        Pattern::Fixed(kw) => {
            if kw.is_empty() {
                return result;
            }
            let finder = memchr::memmem::Finder::new(kw);
            let mut pos = 0;
            while pos <= content.len() {
                match finder.find(&content[pos..]) {
                    Some(off) => {
                        let s = pos + off;
                        result.push(Match {
                            start: s,
                            end: s + kw.len(),
                            replacement: replacement.to_vec(),
                        });
                        pos = s + kw.len();
                    }
                    None => break,
                }
            }
        }
        Pattern::Regex(re) => {
            let re = match re {
                Some(r) => r,
                None => return result,
            };
            let text = match std::str::from_utf8(content) {
                Ok(t) => t,
                Err(_) => return result,
            };
            let rep = String::from_utf8_lossy(replacement).into_owned();
            for caps in re.captures_iter(text) {
                let m = caps.get(0).unwrap();
                let mut dst = String::new();
                caps.expand(&rep, &mut dst);
                result.push(Match {
                    start: m.start(),
                    end: m.end(),
                    replacement: dst.into_bytes(),
                });
            }
        }
    }
    result
}

// ---------------------------------------------------------------------------
// Sorter
// ---------------------------------------------------------------------------

pub struct Sorter {
    pub id: usize,
    pub fixed_order: bool,
}

impl Sorter {
    pub fn run(self, rxs: Vec<Receiver<Msg<PathMatch>>>, tx: Sender<Msg<PathMatch>>) {
        let start = Instant::now();
        let n = rxs.len();
        let mut end_count = 0usize;
        let mut next_seq = 0usize;
        let mut buf: HashMap<usize, PathMatch> = HashMap::new();
        'outer: loop {
            for rx in &rxs {
                match rx.recv() {
                    Ok(Msg::Dat(seq, d)) => {
                        if self.fixed_order {
                            buf.insert(seq, d);
                            while let Some(d) = buf.remove(&next_seq) {
                                let _ = tx.send(Msg::Dat(next_seq, d));
                                next_seq += 1;
                            }
                        } else {
                            let _ = tx.send(Msg::Dat(seq, d));
                        }
                    }
                    Ok(Msg::End) => {
                        end_count += 1;
                        if end_count == n {
                            break 'outer;
                        }
                    }
                    Ok(Msg::Info(m)) => {
                        let _ = tx.send(Msg::Info(m));
                    }
                    Ok(Msg::Err(m)) => {
                        let _ = tx.send(Msg::Err(m));
                    }
                    Ok(Msg::Time(id, b, t)) => {
                        let _ = tx.send(Msg::Time(id, b, t));
                    }
                    Err(_) => {
                        // Abandon the rest of this pass.
                        std::thread::yield_now();
                        break;
                    }
                }
            }
            if end_count == n {
                break;
            }
        }
        let _ = tx.send(Msg::Time(self.id, 0.0, secs(start)));
        let _ = tx.send(Msg::End);
    }
}

// ---------------------------------------------------------------------------
// Replacer
// ---------------------------------------------------------------------------

pub struct Replacer {
    pub id: usize,
    pub interactive: bool,
    pub print_file: bool,
    pub print_column: bool,
    pub print_row: bool,
    pub preserve_time: bool,
    pub console: Arc<Mutex<Console>>,
}

enum Answer {
    Yes,
    No,
    All,
    Quit,
}

fn line_bounds(content: &[u8], start: usize, end: usize) -> (usize, usize) {
    let mut ls = start;
    while ls > 0 {
        let c = content[ls - 1];
        if c == b'\n' || c == b'\r' {
            break;
        }
        ls -= 1;
    }
    let mut le = end;
    while le < content.len() {
        let c = content[le];
        if c == b'\n' || c == b'\r' {
            break;
        }
        le += 1;
    }
    (ls, le)
}

fn line_number(content: &[u8], start: usize) -> usize {
    memchr::memchr_iter(b'\n', &content[..start]).count() + 1
}

fn row_number(content: &[u8], start: usize) -> usize {
    match memchr::memrchr(b'\n', &content[..start]) {
        Some(p) => start - p,
        None => start,
    }
}

impl Replacer {
    pub fn run(self, rx: Receiver<Msg<PathMatch>>, tx: Sender<Msg<PathMatch>>) {
        let start = Instant::now();
        let mut all = false;
        loop {
            match rx.recv() {
                Ok(Msg::Dat(_seq, pm)) => {
                    self.replace(pm, &mut all, &tx);
                }
                Ok(Msg::Info(m)) => {
                    let _ = tx.send(Msg::Info(m));
                }
                Ok(Msg::Err(m)) => {
                    let _ = tx.send(Msg::Err(m));
                }
                Ok(Msg::Time(id, b, t)) => {
                    let _ = tx.send(Msg::Time(id, b, t));
                }
                Ok(Msg::End) => {
                    let _ = tx.send(Msg::Time(self.id, 0.0, secs(start)));
                    let _ = tx.send(Msg::End);
                    break;
                }
                Err(_) => break,
            }
        }
    }

    fn replace(&self, pm: PathMatch, all: &mut bool, tx: &Sender<Msg<PathMatch>>) {
        if pm.matches.is_empty() {
            return;
        }
        let path = &pm.path;
        let content = match fs::read(path) {
            Ok(c) => c,
            Err(e) => {
                let _ = tx.send(Msg::Err(format!("{} @ {:?}", kind_str(&e), path)));
                return;
            }
        };
        let mut out: Vec<u8> = Vec::with_capacity(content.len());
        let mut last = 0usize;
        for m in &pm.matches {
            if m.start < last || m.end > content.len() || m.start > m.end {
                continue;
            }
            let do_replace = if !self.interactive || *all {
                true
            } else {
                self.show(path, &content, m);
                match self.prompt() {
                    Answer::Yes => true,
                    Answer::No => false,
                    Answer::All => {
                        *all = true;
                        true
                    }
                    Answer::Quit => {
                        let mut con = self.console.lock().unwrap();
                        con.reset();
                        std::process::exit(0);
                    }
                }
            };
            out.extend_from_slice(&content[last..m.start]);
            if do_replace {
                out.extend_from_slice(&m.replacement);
            } else {
                out.extend_from_slice(&content[m.start..m.end]);
            }
            last = m.end;
        }
        out.extend_from_slice(&content[last..]);

        if let Err(e) = self.write_file(path, &out) {
            let _ = tx.send(Msg::Err(format!("{} @ {:?}", kind_str(&e), path)));
        }
    }

    fn write_file(&self, path: &Path, data: &[u8]) -> io::Result<()> {
        let real = fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
        let md = fs::metadata(&real)?;
        let dir = real.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from("."));
        let dir = if dir.as_os_str().is_empty() { PathBuf::from(".") } else { dir };
        let mut tmp = tempfile::NamedTempFile::new_in(&dir)?;
        tmp.write_all(data)?;
        tmp.flush()?;
        fs::set_permissions(tmp.path(), md.permissions())?;
        if self.preserve_time {
            let times = fs::FileTimes::new();
            let mut times = times;
            if let Ok(m) = md.modified() {
                times = times.set_modified(m);
            }
            if let Ok(a) = md.accessed() {
                times = times.set_accessed(a);
            }
            let _ = tmp.as_file().set_times(times);
        }
        tmp.persist(&real).map_err(|e| e.error)?;
        Ok(())
    }

    fn show(&self, path: &Path, content: &[u8], m: &Match) {
        let (ls, le) = line_bounds(content, m.start, m.end);
        let mut con = self.console.lock().unwrap();
        let mut prefix_len = 0usize;
        if self.print_file {
            let p = path.to_string_lossy().into_owned();
            con.write_str(Kind::Filename, &p);
            let mut sep = String::from(": ");
            if self.print_column {
                sep.push_str(&format!("{}:", line_number(content, m.start)));
            }
            if self.print_row {
                sep.push_str(&format!("{}:", row_number(content, m.start)));
            }
            con.write_str(Kind::Other, &sep);
            prefix_len = p.chars().count() + sep.chars().count();
        } else {
            let mut s = String::new();
            if self.print_column {
                s.push_str(&format!("{}:", line_number(content, m.start)));
            }
            if self.print_row {
                s.push_str(&format!("{}:", row_number(content, m.start)));
            }
            let s = format!("{:<4}", s);
            con.write_str(Kind::Other, &s);
            prefix_len = s.chars().count();
        }
        let pre = &content[ls..m.start];
        let matched = &content[m.start..m.end];
        let post = &content[m.end..le];
        if !pre.is_empty() {
            con.write(Kind::Text, pre);
        }
        con.write(Kind::MatchText, matched);
        let mut post_nl = post.to_vec();
        post_nl.push(b'\n');
        con.write(Kind::Text, &post_nl);

        let indent = if prefix_len >= 3 { prefix_len - 3 } else { 0 };
        let arrow = format!("{}-> ", " ".repeat(indent));
        con.write_str(Kind::Other, &arrow);
        if !pre.is_empty() {
            con.write(Kind::Text, pre);
        }
        con.write(Kind::MatchText, &m.replacement);
        con.write(Kind::Text, &post_nl);
    }

    fn prompt(&self) -> Answer {
        loop {
            {
                let mut con = self.console.lock().unwrap();
                con.write_str(Kind::Other, "Replace keyword? [Y]es/[n]o/[a]ll/[q]uit: ");
            }
            let mut buf = [0u8; 1];
            let _ = io::stdin().lock().read(&mut buf);
            let c = buf[0] as char;
            {
                let mut con = self.console.lock().unwrap();
                if c == '\n' {
                    con.write_str(Kind::Other, "\n");
                } else {
                    con.write_str(Kind::Other, &format!("{}\n", c));
                }
            }
            let s = c.to_string();
            match s.trim() {
                "y" | "Y" | "" => return Answer::Yes,
                "n" | "N" => return Answer::No,
                "a" | "A" => return Answer::All,
                "q" | "Q" => return Answer::Quit,
                _ => continue,
            }
        }
    }
}
